"""Execution authorization is generated by the host and bound to one branch."""

from dataclasses import dataclass
import math
from typing import Protocol

from ..contracts import ExecutionRequest


@dataclass(frozen=True)
class RunAuthorization:
    authorization_id: str
    source_binding: dict
    resource_budget: dict

    def validate(self, request: ExecutionRequest) -> None:
        if dict(request.source_binding) != self.source_binding:
            raise ValueError("authorization_binding_mismatch")
        if request.network_enabled and not self.resource_budget["network_enabled"]:
            raise ValueError("network_not_authorized")
        for field, value in (("cpu_cores", request.cpu_cores), ("memory_mb", request.memory_mb),
                             ("max_execution_seconds", request.max_wall_seconds)):
            if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or value <= 0 or value > self.resource_budget[field]:
                raise ValueError(f"authorization_resource_exceeded:{field}")


class ExperimentRuntime(Protocol):
    def run(self, request: ExecutionRequest, authorization: RunAuthorization, *, cancel=None) -> dict: ...
    def cancel(self, container_name: str) -> None: ...
